import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/%E3%82%A2%E3%83%97%E3%83%AA%E3%81%8C%E7%B0%A1%E5%8D%98%E3%81%AB%E4%BD%9C%E3%82%8C%E3%82%8B%E6%99%82%E4%BB%A3.html","title":"アプリが簡単に作れる時代","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":1.23,"words":368},"filePathRelative":"アプリが簡単に作れる時代.md"}`),a={name:`アプリが簡単に作れる時代.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="アプリが簡単に作れる時代" tabindex="-1"><a class="header-anchor" href="#アプリが簡単に作れる時代"><span>アプリが簡単に作れる時代</span></a></h1><p><a href="./ボツエッセイ.html">ボツエッセイ</a></p><p>コーディングagentによりアプリが簡単に作れるようになった帰結を考える。</p><ul><li>iPhoneがいまいちになる</li><li>安いAndroid端末の価値がハイエンドと比較して相対的に上る</li><li>大企業の方針に従わなくて良くなる <ul><li>大企業がユーザーの行動に影響を与えるのが難しくなる</li></ul></li><li>他人にアプリを使ってもらうのが難しくなる</li></ul><p>安いAndroid端末の価値が上るのは、簡単にアプリが作れる恩恵を全て受けるから。 新しい端末にしなくても突然いろんなアプリを作って動かす事が出来るようになり、価値が跳ね上がった。 買い替えた訳じゃないのに突然自分のスマホがいろんなアプリを自由に動かせるデバイスに化けた。</p><p>自分のMoto g53yも、突然好きなアプリがぱっと作れて、どんどん便利になっていていってる。 端末自体は変わらないのに価値がまったくの別物に化けた。</p><p>これはメーカーなどの努力では無く、完全に外部要因だ、というのが重要だ。 売り手が付加価値をつけたのではなく、勝手についてしまった。 買い替え需要などをコントロール出来ない。</p><p>ハイエンド端末も同じ恩恵を受けるが、ハイエンドゆえの追加要素がコーディングagent関連ではほとんど無い。 1円あたりの価値に換算するとハイエンドほど下がってしまう。 勝手に生まれた価値がすさまじいので、これが落ち着くまではローエンドからミドルエンドのスマホの時代が続くんじゃないか。</p><p>これまで大企業のサービスの方針が、好きじゃないものでもある程度従っていたのは、 大企業の作るものを自分で作るのは大変だったからだ。 今でも大企業の作るものを自分で作るのは大変だが、 自分専用で使う機能だけに削ったもので良ければ割と作れるようになってきた。</p><p>これまでは自分専用のためだけにアプリを作るのは労力的に躊躇していたが、 今は自分専用で作ってもいいくらいに労力が下がったので、 自分が使う機能だけに絞った自分専用アプリが選択肢に入るようになった。 結果として大企業のアプリを使わずに自分専用の機能限定アプリで良くなってきた。</p><p>大企業はこれまでほど自分達の意思に従ってもらうのが難しくなるので、 よりユーザーに低姿勢にならないといけないんじゃないか。これは良い傾向だと思う。</p><p>また、たくさんの機能を追加していく事で競合を倒すというマンパワー重視の大企業の戦術は、 使いにくくなったと思う。これも大企業には不利に働くかもしれない。</p><p>自分のアプリは自分で好きに簡単に作れるようになったので、 他人が作ったものを使う理由は減ったと思う。 これはコーティングエージェント使うと簡単なライブラリはあまり使わなくなるのに似ている。 他人が作ったものを探すよりも今必要なものを作る方が簡単だし満足がいくものが多い。</p><p>アプリも同じように他人が作ったものを試すよりも自分で作った方が良くなる。 すると自分が作ったものを他の人に使ってもらうのも難しくなる気がする。</p><p>コーディングagentの恩恵を最大限活かすなら、他人を動かすのではなく自分の環境を良くするのが良い気がする。</p><p>作ったアプリを自慢する場合は使ってもらうよりもそれを自分が使っている様をコンテンツにしたりしていく方がいいのでは？</p>`,16)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};